// DEV-ONLY harness. Phase 2's chat agent calls these tools directly through Execute Workflow;
// this webhook exists so the tools can be exercised end-to-end (real trigger -> real sub-workflow
// -> real Postgres) before any agent exists, and so the QA script can assert their JSON.
const IDS = {
  "find_availability": "@@WF:20 · tool: find availability@@",
  "create_booking": "@@WF:21 · tool: create booking@@",
  "cancel_booking": "@@WF:22 · tool: cancel booking@@",
  "find_stylist_alternatives": "@@WF:23 · tool: find stylist alternatives@@",
  "chat": "@@WF:10 · Booking Agent Core@@",
  "send_notification": "@@WF:39 · send a notice (exactly once)@@",
  "reminder_sweep": "@@WF:30 · scheduled reminders@@",
  "backfill_run": "@@WF:31 · cancellation backfill@@",
  "stylist_decline": "@@WF:32 · stylist decline → client consent@@",
  "reassign_booking": "@@WF:24 · tool: reassign booking@@",
  "review_sweep": "@@WF:40 · ask for a review@@",
  "submit_review": "@@WF:41 · tool: submit review@@"
};
// This endpoint can invoke create_booking, cancel_booking, reassign_booking and submit_review
// with caller-supplied arguments, and refs come from a sequence, so they are guessable. It
// therefore fails CLOSED: no HARNESS_TOKEN configured means it refuses everything, and the
// importer never activates it. Set HARNESS_TOKEN only to run the verify scripts.
let expected = '';
try { expected = $env.HARNESS_TOKEN || ''; } catch (e) { expected = ''; }
const headers = (($input.first() || {}).json || {}).headers || {};
const supplied = String(headers['x-harness-token'] || '');
if (!expected) {
  return [{ json: { ok: false, reason: 'harness_token_not_configured' } }];
}
if (supplied !== expected) {
  return [{ json: { ok: false, reason: 'forbidden' } }];
}

const out = [];
for (const item of $input.all()) {
  const body = (item.json && item.json.body) || {};
  const tool = String(body.tool || '').trim();
  const id = IDS[tool];
  if (!id) return [{ json: { _unknown_tool: tool, ok: false, reason: 'unknown_tool' } }];
  // `inputs: [...]` fans out, so the multi-item contract can be exercised: a Code node that
  // reads $json instead of $input.all() collapses this to one item and silently drops bookings.
  const many = Array.isArray(body.inputs) ? body.inputs : null;
  for (const one of (many || [body.input || {}])) {
    out.push({ json: Object.assign({}, one, { _workflow_id: id }) });
  }
}
return out;
